<?php
require __DIR__.'/includes/bootstrap.php';require_login();require_member($pdo);
$member=current_member($pdo);$error='';$notice='';
if($_SERVER['REQUEST_METHOD']==='POST'){
    verify_csrf();$action=$_POST['action']??'create';
    try{
        if($action==='create'){
            $name=trim((string)($_POST['name']??''));$amount=parse_amount_ro((string)($_POST['amount']??''));$category=trim((string)($_POST['category']??''));$due=parse_ro_date((string)($_POST['due_date']??''));$bucket=in_array($_POST['bucket']??'fixed',['fixed','variable'],true)?$_POST['bucket']:'fixed';$notes=trim((string)($_POST['notes']??''));
            if($name===''||$amount<=0||!$due)throw new RuntimeException('Completează denumirea, suma și scadența.');
            $s=$pdo->prepare("INSERT INTO scheduled_expenses(name,amount,category,due_date,bucket,notes,created_by_member_id) VALUES(?,?,?,?,?,?,?)");$s->execute([$name,$amount,$category?:null,$due,$bucket,$notes?:null,current_member_id()]);$id=(int)$pdo->lastInsertId();log_activity($pdo,'scheduled_added','scheduled_expense',$id,$name.' · '.money_ro($amount));$notice='Cheltuiala programată a fost adăugată.';
        }elseif($action==='pay'){
            $id=(int)($_POST['id']??0);$paid=parse_ro_date((string)($_POST['paid_date']??date('d.m.Y')),date('Y-m-d'));
            $q=$pdo->prepare("SELECT * FROM scheduled_expenses WHERE id=? AND status='pending'");$q->execute([$id]);$item=$q->fetch();if(!$item)throw new RuntimeException('Cheltuiala nu mai este disponibilă.');
            $pdo->beginTransaction();$ins=$pdo->prepare('INSERT INTO transactions(type,name,amount,category,transaction_date,created_by_member_id) VALUES(?,?,?,?,?,?)');$ins->execute(['expense',$item['name'],$item['amount'],$item['category']?:null,$paid.' '.date('H:i:s'),current_member_id()]);$tx=(int)$pdo->lastInsertId();add_transaction_meta($pdo,$tx,'scheduled',$item['bucket'],(int)$item['id']);$u=$pdo->prepare("UPDATE scheduled_expenses SET status='paid',paid_date=?,transaction_id=? WHERE id=?");$u->execute([$paid,$tx,$id]);$pdo->commit();log_activity($pdo,'scheduled_paid','scheduled_expense',$id,$item['name'].' · '.money_ro($item['amount']));$notice='Marcată ca plătită și adăugată în tranzacții.';
        }elseif($action==='cancel'){
            $id=(int)($_POST['id']??0);$pdo->prepare("UPDATE scheduled_expenses SET status='cancelled' WHERE id=? AND status='pending'")->execute([$id]);$notice='Cheltuiala a fost anulată.';
        }
    }catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$error=$e->getMessage();}
}
$rows=$pdo->query("SELECT s.*,m.name creator_name FROM scheduled_expenses s LEFT JOIN family_members m ON m.id=s.created_by_member_id WHERE s.status='pending' ORDER BY s.due_date,s.id")->fetchAll();
$pageTitle='Cheltuieli programate';$active='money';$backUrl='/money.php';require __DIR__.'/includes/layout_top.php';
?>
<?php if($error):?><div class="alert error"><?=e($error)?></div><?php endif;?><?php if($notice):?><div class="alert success"><?=e($notice)?></div><?php endif;?>
<section class="scheduled-intro"><div><h2>Nu o plăti înainte de vreme</h2><p>Adaugă rata sau orice plată viitoare cu scadență. Intră în cheltuieli abia când apeși „Plătită”.</p></div><button class="btn primary small" data-toggle-target="#scheduledForm"><?=icon('plus')?> Adaugă</button></section>
<section id="scheduledForm" class="settings-card" hidden><form method="post" class="form-stack"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="create"><label>Denumire<div class="input-wrap"><?=icon('receipt')?><input name="name" required placeholder="Ex: Rată credit"></div></label><label>Sumă<div class="input-wrap money-input"><?=icon('wallet')?><input name="amount" inputmode="decimal" required placeholder="600,00"><span>lei</span></div></label><label>Categorie<div class="input-wrap"><?=icon('tag')?><select name="category"><option value="">Fără categorie</option><?php foreach(category_options() as $cat):?><option><?=e($cat)?></option><?php endforeach;?></select></div></label><div class="two-col"><label>Scadență<input class="ro-date" name="due_date" inputmode="numeric" maxlength="10" placeholder="ZZ.LL.AAAA" required></label><label>Tip<select name="bucket"><option value="fixed">Cost fix</option><option value="variable">Cost variabil</option></select></label></div><label>Notițe<textarea name="notes" rows="3" placeholder="Opțional"></textarea></label><button class="btn primary wide">Salvează programarea</button></form></section>
<section><div class="section-head"><div><h2>În așteptare</h2><p class="section-subtle"><?=count($rows)?> plăți programate</p></div></div><div class="scheduled-list"><?php if(!$rows):?><div class="empty-card">Nu ai cheltuieli programate.</div><?php endif;?><?php foreach($rows as $r):$days=days_until($r['due_date']);?><article class="scheduled-row <?=$days!==null&&$days<0?'overdue':(($days!==null&&$days<=3)?'soon':'')?>"><div class="scheduled-main"><div class="scheduled-icon"><?=icon('calendar')?></div><div><strong><?=e($r['name'])?></strong><span><?=e(date_ro($r['due_date']))?> · <?=e(short_due_label($r['due_date']))?><?php if($r['category']):?> · <?=e($r['category'])?><?php endif;?></span></div></div><div class="scheduled-amount"><?=money_ro($r['amount'])?></div><div class="scheduled-actions"><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="pay"><input type="hidden" name="id" value="<?=$r['id']?>"><input type="hidden" name="paid_date" value="<?=e(date('d.m.Y'))?>"><button class="btn primary small">Plătită</button></form><form method="post" onsubmit="return confirm('Anulezi această plată programată?')"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="cancel"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="btn ghost small">Anulează</button></form></div></article><?php endforeach;?></div></section>
<?php require __DIR__.'/includes/layout_bottom.php';?>
